<?php
require dirname(__DIR__).'/cms/bootstrap.php';
require dirname(__DIR__).'/cms/requests.php';
require dirname(__DIR__).'/cms/institution.php';
header('Cache-Control: no-store'); header('X-Robots-Tag: noindex, nofollow');
$view=$_GET['view']??'dashboard'; $error=''; $notice=$_SESSION['notice']??''; unset($_SESSION['notice']);
if($_SERVER['REQUEST_METHOD']==='POST') {
    check_csrf(); $action=$_POST['action']??'';
    try {
        if($action==='login') {
            $key='login:'.hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'',setting('salt'));
            $limit=query('SELECT * FROM limits WHERE key=?',[$key])->fetch();
            if($limit&&$limit['expires']>time()&&$limit['attempts']>=5) throw new RuntimeException('Trop de tentatives. Patientez quinze minutes.');
            $account=query('SELECT * FROM users WHERE login=?',[trim((string)($_POST['login']??''))])->fetch();
            if(!$account||!password_verify((string)($_POST['password']??''),$account['password'])) {
                $attempts=($limit&&$limit['expires']>time()?$limit['attempts']:0)+1;
                query('INSERT INTO limits(key,attempts,expires) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET attempts=excluded.attempts,expires=excluded.expires',[$key,$attempts,time()+900]);
                security_event('login_failed');
                throw new RuntimeException('Identifiant ou mot de passe incorrect.');
            }
            session_regenerate_id(true); $_SESSION['user_id']=$account['id']; $_SESSION['last_active']=time(); $_SESSION['issued_at']=time(); $_SESSION['auth_signature']=hash('sha256',$account['password']); security_event('login_ok',(int)$account['id']); $_SESSION['csrf']=bin2hex(random_bytes(32)); query('DELETE FROM limits WHERE key=?',[$key]); go(url('admin'));
        }
        $account=user(); if(!$account) {http_response_code(401);exit('Connectez-vous avant de continuer.');}
        if($action==='logout') {security_event('logout',(int)$account['id']);$_SESSION=[];session_destroy();go(url('admin'));}
        if($action==='password') {
            $old=query('SELECT password FROM users WHERE id=?',[$account['id']])->fetchColumn();
            if(!password_verify((string)($_POST['old_password']??''),$old)) throw new RuntimeException('Votre mot de passe actuel est incorrect.');
            $new=(string)($_POST['new_password']??'');
            if(mb_strlen($new)<12||strlen($new)>200||$new!==($_POST['confirm_password']??'')) throw new RuntimeException('Choisissez au moins 12 caractères et répétez le même mot de passe.');
            query('UPDATE users SET password=? WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$account['id']]);$_SESSION['auth_signature']=hash('sha256',query('SELECT password FROM users WHERE id=?',[$account['id']])->fetchColumn());$_SESSION['csrf']=bin2hex(random_bytes(32));security_event('password_changed',(int)$account['id']);session_regenerate_id(true);$_SESSION['notice']='Mot de passe modifié. Le fichier des anciens accès ne sera plus à jour.';go(url('admin').'?view=account');
        }
        if(in_array($action,['save','trash','restore','restore_revision'],true)) {
            $id=(int)($_POST['id']??0); $old=$id?query('SELECT * FROM contents WHERE id=?',[$id])->fetch():null;
            if($id&&!$old) throw new RuntimeException('Ce contenu n’existe plus.');
            db()->exec('BEGIN IMMEDIATE');
            try {
                if($old) { $current=query('SELECT * FROM contents WHERE id=?',[$id])->fetch(); if((int)($_POST['version']??0)!==$current['version']) throw new RuntimeException('Ce contenu a été modifié ailleurs. Rechargez la page avant de poursuivre.'); revision($current); }
                if($action==='trash'||$action==='restore') {
                    if($old['kind']==='page') throw new RuntimeException('Les rubriques principales ne peuvent pas être supprimées.');
                    query('UPDATE contents SET status=?,version=version+1 WHERE id=?',[$action==='trash'?'trash':'draft',$id]);
                } elseif($action==='restore_revision') {
                    $row=query('SELECT snapshot FROM revisions WHERE id=? AND content_id=?',[(int)$_POST['revision'],$id])->fetchColumn();
                    if(!$row) throw new RuntimeException('Version introuvable.'); $v=json_decode($row,true);
                    query('UPDATE contents SET title=?,excerpt=?,content=?,images=?,posted_at=?,status=?,version=version+1 WHERE id=?',[$v['title'],$v['excerpt'],$v['content'],$v['images'],$v['posted_at'],'draft',$id]);
                } else {
                    $kind=$old['kind']??($_POST['kind']??'');
                    if(!in_array($kind,['news','activity','page'],true)||(!$old&&$kind==='page')) throw new RuntimeException('Type de contenu invalide.');
                    $title=trim((string)($_POST['title']??'')); $excerpt=trim(strip_tags((string)($_POST['excerpt']??'')));
                    if(!$title||mb_strlen($title)>180||mb_strlen($excerpt)>600) throw new RuntimeException('Indiquez un titre de 180 caractères maximum et un résumé de 600 caractères maximum.');
                    $raw=(string)($_POST['content']??''); if(strlen($raw)>250000) throw new RuntimeException('Le contenu est trop volumineux.');
                    $content=clean_html($raw); if(!trim(strip_tags($content))&&!str_contains($content,'<img')) throw new RuntimeException('Ajoutez le texte du contenu.');
                    $posted=DateTime::createFromFormat('Y-m-d\TH:i',(string)($_POST['posted_at']??''));
                    if(!$posted||$posted->format('Y-m-d\TH:i')!==$_POST['posted_at']) throw new RuntimeException('Date et heure invalides.');
                    $status=$_POST['status']??'draft'; if(!in_array($status,['draft','published'],true)) throw new RuntimeException('Statut invalide.');
                    $ims=[]; $available=$old?images($old):[];
                    foreach($_POST['keep_images']??[] as $index) if(isset($available[(int)$index])) { $im=$available[(int)$index];$im['alt']=mb_substr(trim((string)($_POST['image_alt'][(int)$index]??$im['alt'])),0,250);$ims[]=$im; }
                    $library=setting('media',[]);
                    foreach($_POST['library_images']??[] as $index) if(isset($library[(int)$index])) $ims[]=$library[(int)$index];
                    $newImages=upload_images(); $ims=array_merge($ims,$newImages); if(count($ims)>30) throw new RuntimeException('Conservez au maximum 30 images par publication.');
                    // Removed images must not reappear via the original imported HTML.
                    if($old&&$available) { foreach($available as $im) if(!in_array($im['src'],array_column($ims,'src'),true)) $content=preg_replace('#<img\b[^>]*src=["\']'.preg_quote($im['src'],'#').'["\'][^>]*>#i','',$content); }
                    if($newImages) set_setting('media',array_merge($library,$newImages));
                    if($old) query('UPDATE contents SET title=?,excerpt=?,content=?,posted_at=?,images=?,status=?,version=version+1 WHERE id=?',[$title,$excerpt,$content,$posted->format('Y-m-d H:i:s'),json_encode($ims),$status,$id]);
                    else {
                        $slug=slugify($title);$base=$slug;$n=2;while(query('SELECT id FROM contents WHERE slug=?',[$slug])->fetch())$slug=$base.'-'.$n++;
                        if(in_array($slug,['admin','envoyer','sitemap-xml'],true))$slug.='-publication';
                        query('INSERT INTO contents(kind,slug,title,excerpt,content,posted_at,images,status) VALUES(?,?,?,?,?,?,?,?)',[$kind,$slug,$title,$excerpt,$content,$posted->format('Y-m-d H:i:s'),json_encode($ims),$status]);$id=(int)db()->lastInsertId();
                    }
                }
                db()->exec('COMMIT');
            } catch(Throwable $ex) {db()->exec('ROLLBACK');throw $ex;}
            $_SESSION['notice']=$action==='trash'?'Contenu déplacé dans la corbeille.':($action==='restore'?'Contenu restauré en brouillon.':'Contenu enregistré.');
            go(url('admin').($action==='save'||$action==='restore_revision'?'?view=edit&id='.$id:'?view='.($old['kind']==='news'?'news':'activity')));
        }
        if($account['role']!=='admin') {http_response_code(403);exit('Action réservée à l’administrateur.');}
        if($action==='institution') {save_institution_profile($_POST);$_SESSION['notice']='Informations institutionnelles enregistrées.';go(url('admin').'?view=institution');}
        if(str_starts_with((string)$action,'request_')) { requests_schema(); request_action($action,$account); }
        if($action==='settings') {
            $config=setting('contact',[]);
            $sheet=trim((string)($_POST['sheet_url']??'')); $script=trim((string)($_POST['script_url']??''));
            if($sheet&&!preg_match('#^https://docs\.google\.com/spreadsheets/d/[A-Za-z0-9_-]+#',$sheet))throw new RuntimeException('Lien Google Sheets invalide.');
            if($script&&!preg_match('#^https://script\.google\.com/macros/s/[A-Za-z0-9_-]+/exec$#',$script))throw new RuntimeException('URL Apps Script invalide.');
            $config['sheet_url']=$sheet;$config['script_url']=$script;if(!empty($_POST['script_token']))$config['script_token']=$_POST['script_token'];set_setting('contact',$config);$_SESSION['notice']='Paramètres enregistrés.';go(url('admin').'?view=stats');
        }
        if($action==='sync') {
            $config=setting('contact',[]);$target=$config['script_url']??'';
            if(!preg_match('#^https://script\.google\.com/macros/s/[A-Za-z0-9_-]+/exec$#',$target)||empty($config['script_token']))throw new RuntimeException('Configurez le connecteur avant de synchroniser. Les exports restent disponibles.');
            $curl=curl_init($target);curl_setopt_array($curl,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['token'=>$config['script_token'],'data'=>export_stats()]),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>25,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);
            $reply=curl_exec($curl);$code=curl_getinfo($curl,CURLINFO_HTTP_CODE);$redirect=curl_getinfo($curl,CURLINFO_REDIRECT_URL);curl_close($curl);
            if(in_array($code,[302,303],true)&&preg_match('#^https://script\.googleusercontent\.com/#',$redirect)) { $curl=curl_init($redirect);curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);$reply=curl_exec($curl);$code=curl_getinfo($curl,CURLINFO_HTTP_CODE);curl_close($curl); }
            $ok=$code===200&&!empty(json_decode($reply?:'{}',true)['ok']);set_setting('sync_result',($ok?'Réussie':'Échec').' le '.date('d/m/Y H:i'));if(!$ok)throw new RuntimeException('La synchronisation a échoué. Les données locales sont conservées.');$_SESSION['notice']='Synchronisation réussie.';go(url('admin').'?view=stats');
        }
        if($action==='backup_full') { $path=full_backup_service()->create();security_event('backup_created',(int)$account['id']);header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.basename($path).'"');header('Content-Length: '.filesize($path));readfile($path);exit; }
        if($action==='backup') { $path=PRIVATE_DIR.'/cms-sauvegarde-'.bin2hex(random_bytes(8)).'.sqlite';db()->exec('VACUUM INTO '.db()->quote($path));header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="fecgd-sauvegarde-'.date('Ymd-His').'.sqlite"');readfile($path);exit; }
    } catch(Throwable $ex) { $error=$ex instanceof RuntimeException && !($ex instanceof PDOException)?$ex->getMessage():'L’opération a échoué. Vos données déjà enregistrées sont conservées.'; }
}
$account=user();
if($account&&$view==='export') {
    if($account['role']!=='admin'){http_response_code(403);exit;}
    $format=$_GET['format']??'json';$data=export_stats();
    if($format==='json'){header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="fecgd-statistiques.json"');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);}
    else {header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="fecgd-statistiques.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');foreach($data[$format==='inscriptions'?'inscriptions':'visites'] as $row)fputcsv($out,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\-\t\r]/',$v)?"'".$v:$v,$row),';');}exit;
}
if($account&&$account['role']!=='admin'&&in_array($view,['requests','stats','maintenance','institution'],true)){http_response_code(403);exit('Accès réservé à l’administrateur.');}
if($account&&$account['role']==='admin'&&$view==='requests') { requests_schema(); if(($_GET['export']??'')==='csv')request_csv(request_filters($_GET)); }
function admin_button(string $action,array $post,string $label): string {return '<form method="post" class="inline">'.token_input().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.(int)$post['id'].'"><input type="hidden" name="version" value="'.(int)$post['version'].'"><button '.($action==='trash'?'data-confirm="Déplacer ce contenu dans la corbeille ?"':'').'>'.e($label).'</button></form>';}
