<?php elseif(in_array($view,['news','activity','pages','trash'],true)): $kind=$view==='pages'?'page':$view;$search=trim((string)($_GET['q']??''));$items=$view==='trash'?query("SELECT * FROM contents WHERE status='trash' ORDER BY posted_at DESC")->fetchAll():query("SELECT * FROM contents WHERE kind=? AND status!='trash' AND (title LIKE ? OR excerpt LIKE ?) ORDER BY posted_at DESC,id DESC",[$kind,'%'.$search.'%','%'.$search.'%'])->fetchAll();?><h1><?=e(['news'=>'Actualités','activity'=>'Activités','pages'=>'Pages du site','trash'=>'Corbeille'][$view])?></h1><?php if(in_array($view,['news','activity'],true)):?><a class="primary" href="<?=url('admin')?>?view=edit&kind=<?=$view?>">Ajouter <?=$view==='news'?'une actualité':'une activité'?></a><?php endif;?><form method="get" class="search"><input type="hidden" name="view" value="<?=e($view)?>"><input name="q" placeholder="Rechercher un titre" value="<?=e($search)?>"><button>Rechercher</button></form><?php if(!$items):?><p class="panel">Aucun contenu pour le moment.<?php if($view==='activity'):?> La page de présentation des activités est conservée : <a href="<?=url('admin')?>?view=pages">modifier les pages</a>.<?php endif;?></p><?php endif;?><div class="records"><?php foreach($items as $item):?><article class="panel record"><div><span class="badge"><?=e(['published'=>$item['posted_at']>date('Y-m-d H:i:s')?'Programmé':'Publié','draft'=>'Brouillon','trash'=>'Corbeille'][$item['status']])?></span><h2><?=e($item['title'])?></h2><p><?=e(date('d/m/Y H:i',strtotime($item['posted_at'])))?> · <?=count(images($item))?> photo(s)</p></div><div class="actions"><?php if($view==='trash'):echo admin_button('restore',$item,'Restaurer en brouillon');else:?><a href="<?=url('admin')?>?view=edit&id=<?=$item['id']?>">Modifier</a><a target="_blank" rel="noopener" href="<?=url($item['slug']==='accueil'?'':$item['slug'])?>?apercu=1">Aperçu ↗</a><?php if($kind!=='page')echo admin_button('trash',$item,'Supprimer');endif;?></div></article><?php endforeach;?></div>
<?php elseif($view==='edit'):
    $item=isset($_GET['id'])?query('SELECT * FROM contents WHERE id=?',[(int)$_GET['id']])->fetch():null;
